def T(title, group, level, vi, formula, usage, signals, examples, notes, compare, mistakes, exercises, video, page):
    return {
        "title": title, "slug": re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-"), "group": group, "level": level,
        "description": vi, "formula": formula, "usage": usage, "signals": signals,
        "examples": [{"en": e, "vi": v} for e, v in examples], "notes": notes, "compare": compare,
        "common_mistakes": [{"wrong": w, "right": r} for w, r in mistakes],
        "exercises": [{"question": q, "options": o, "answer": a, "explanation": x} for q, o, a, x in exercises],
        "video": video, "source": ZIM + page,
    }


